-- =====================================================================
-- Helper Academy — v8: Unit 6 word clips and the song "Never Gonna Slow Us Down"
-- Run AFTER supabase_v7_song_timing.sql (safe to run more than once).
-- =====================================================================
update public.set_items i set video_url = 'assets/videos/' || v.slug || '.mp4?v=20261117'
from (values ('Stooping','stooping'),('Boughs','boughs'),('Fern','fern'),('Moss','moss'),('Rover','rover'),('Wren','wren'),
             ('Affluent','affluent'),('Majority','majority'),('Simultaneously','simultaneously'),('Renowned','renowned'),
             ('Deteriorating','deteriorating')) as v(term, slug)
where i.set_id = '00000000-0000-4000-8000-000000000005' and i.term = v.term;

-- The Unit 6 song (video edition: word clips + lyrics on screen). Times from the song's own timed lyrics.
insert into public.set_songs (id, set_id, text_id, unit, title, media_url, lines, position)
values ('00000000-0000-4000-8000-0000000006b1', '00000000-0000-4000-8000-000000000005', null, 6, 'Never Gonna Slow Us Down',
        'assets/songs/never-gonna-slow-us-down-words.mp4?v=20261117', '[{"t": 0.6, "e": 3.1, "l": "(Hey! Ho! Let''s go!)"}, {"t": 3.1, "e": 6.0, "l": "(Stomp, stomp, clap!)"}, {"t": 6.0, "e": 10.74, "l": "We learn these words, and we shout them out loud!"}, {"t": 10.74, "e": 14.83, "l": "You are never gonna slow us down!"}, {"t": 14.83, "e": 19.69, "l": "Renowned means famous, admired by a crowd!"}, {"t": 19.69, "e": 23.89, "l": "You are never gonna slow us down!"}, {"t": 23.89, "e": 28.51, "l": "Deteriorating, getting worse over time!"}, {"t": 28.51, "e": 33.13, "l": "You are never gonna slow us down!"}, {"t": 33.13, "e": 37.23, "l": "A Rover is a traveler walking town to town"}, {"t": 37.23, "e": 41.32, "l": "Past the Boughs, the tree branches hanging down"}, {"t": 41.32, "e": 45.64, "l": "A tiny brown Wren sings a song in the tree"}, {"t": 45.64, "e": 50.19, "l": "While soft green Moss covers rocks by the sea"}, {"t": 50.19, "e": 54.73, "l": "The Fern has leafy feathers growing in the shade"}, {"t": 54.73, "e": 58.96, "l": "Stooping down, bending low, look at what we made!"}, {"t": 58.96, "e": 63.63, "l": "We learn these words, and we shout them out loud!"}, {"t": 63.63, "e": 67.39, "l": "You are never gonna slow us down!"}, {"t": 67.39, "e": 72.31, "l": "Affluent means rich with a house big and proud!"}, {"t": 72.31, "e": 75.91, "l": "You are never gonna slow us down!"}, {"t": 75.91, "e": 80.36, "l": "Majority is more than half of the group!"}, {"t": 80.36, "e": 85.64, "l": "Simultaneously, at the same time we swoop!"}, {"t": 85.64, "e": 87.11, "l": "What''s a traveler? (Rover!)"}, {"t": 87.11, "e": 88.65, "l": "Tree branches? (Boughs!)"}, {"t": 88.65, "e": 90.31, "l": "Bending low? (Stooping!)"}, {"t": 90.31, "e": 91.87, "l": "Famous? (Renowned!)"}, {"t": 91.87, "e": 94.24, "l": "Little brown songbird? (Wren!)"}, {"t": 94.24, "e": 99.48, "l": "At the exact same time? (Simultaneously!)"}, {"t": 99.48, "e": 104.23, "l": "We learn these words, and we shout them out loud!"}, {"t": 104.23, "e": 107.78, "l": "You are never gonna slow us down!"}, {"t": 107.78, "e": 113.01, "l": "We''re Grade 5 champions and we''re ready to shine!"}, {"t": 113.01, "e": 115.75, "l": "You are never gonna slow us down!"}, {"t": 115.75, "e": 121.0, "l": "(Hey! Hey! Hey!)"}]'::jsonb, 1)
on conflict (id) do update set title = excluded.title, media_url = excluded.media_url, lines = excluded.lines, unit = excluded.unit;
